/* Email-safe table layouts with escaped text and restricted link protocols. */
(function(root){
const fonts={arial:'Arial, Helvetica, sans-serif',verdana:'Verdana, Geneva, sans-serif',georgia:'Georgia, Times New Roman, serif',tahoma:'Tahoma, Arial, sans-serif'};
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function url(value,label,image=false){if(!value?.trim())return '';let text=value.trim();if(!/^[a-z][a-z\d+.-]*:/i.test(text))text='https://'+text;let parsed;try{parsed=new URL(text)}catch{throw Error(label+': URL chưa hợp lệ.')}if(!['https:','http:'].includes(parsed.protocol)||image&&parsed.protocol!=='https:'||parsed.username||parsed.password)throw Error(label+': dùng URL '+(image?'HTTPS':'HTTP hoặc HTTPS')+' và không chứa tài khoản/mật khẩu.');return parsed.href;}
function build(data){const name=(data.name||'').trim();if(!name)throw Error('Nhập họ tên để tạo chữ ký.');const accent=/^#[0-9a-f]{6}$/i.test(data.accent)?data.accent:'#236b52',color=/^#[0-9a-f]{6}$/i.test(data.color)?data.color:'#33443b',background=/^#[0-9a-f]{6}$/i.test(data.background)?data.background:'#ffffff';const font=fonts[data.font]||fonts.arial,size=Math.max(12,Math.min(18,Number(data.size)||14)),imageSize=Math.max(48,Math.min(120,Number(data.imageSize)||80));const website=url(data.website,'Website'),logo=url(data.logo,'Logo',true);const email=(data.email||'').trim();if(email&&!/^[^\s<>@]+@[^\s<>@]+\.[^\s<>@]+$/.test(email))throw Error('Email chưa hợp lệ. Ví dụ: ban@example.com');
const link=(href,label)=>`<a href="${esc(href)}" target="_blank" rel="noopener noreferrer" style="color:${accent};text-decoration:none;font-family:${font};font-size:${size}px;">${esc(label)}</a>`;
const rows=[];const plain=[name];const job=[data.title,data.company].filter(x=>x?.trim()).join(' · ');if(job)plain.push(job);
if(email){rows.push(['Email',link('mailto:'+encodeURIComponent(email),email)]);plain.push('Email: '+email)}
for(const [key,label] of [['phone','Điện thoại'],['mobile','Di động']])if(data[key]?.trim()){const value=data[key].trim();if(!/^[+\d\s().-]{3,40}$/.test(value))throw Error(label+': chỉ nhập số điện thoại và dấu + ( ) . -');rows.push([label,link('tel:'+value.replace(/[^+\d]/g,''),value)]);plain.push(label+': '+value)}
if(website){rows.push(['Website',link(website,data.website.trim().replace(/^https?:\/\//i,''))]);plain.push('Website: '+website)}if(data.address?.trim()){rows.push(['Địa chỉ',esc(data.address).replace(/\n/g,'<br>')]);plain.push('Địa chỉ: '+data.address.trim())}
const socials=[];for(const [key,label] of [['linkedin','LinkedIn'],['facebook','Facebook'],['instagram','Instagram'],['github','GitHub'],['twitter','X / Twitter'],['custom',data.customLabel?.trim()||'Liên kết']]){const href=url(data[key],label);if(href){socials.push(link(href,label));plain.push(label+': '+href)}}
const contacts=rows.map(([label,value])=>`<tr><td valign="top" style="padding:3px 12px 3px 0;color:${color};font-size:${size-1}px;white-space:nowrap;">${label}</td><td style="padding:3px 0;color:${color};font-size:${size}px;">${value}</td></tr>`).join('');
const details=`<table role="presentation" cellpadding="0" cellspacing="0" border="0" style="font-family:${font};color:${color};"><tr><td colspan="2" style="font-size:${size+6}px;font-weight:bold;line-height:1.4;color:${accent};padding:0 0 4px;">${esc(name)}</td></tr>${job?`<tr><td colspan="2" style="font-size:${size}px;padding:0 0 12px;color:${color};">${esc(job)}</td></tr>`:''}${contacts}${socials.length?`<tr><td colspan="2" style="padding-top:12px;font-size:${size}px;">${socials.join(' &nbsp;·&nbsp; ')}</td></tr>`:''}</table>`;
const image=logo?`<img src="${esc(logo)}" alt="${esc(data.company||name)}" width="${imageSize}" style="display:block;width:${imageSize}px;max-width:${imageSize}px;height:auto;border:0;" />`:'';let content;if(data.template==='compact')content=`${image?`<tr><td style="padding:0 0 16px;">${image}</td></tr>`:''}<tr><td>${details}</td></tr>`;else if(data.template==='banner')content=`<tr><td style="border-top:4px solid ${accent};padding-top:16px;">${image?`<table role="presentation" cellpadding="0" cellspacing="0" border="0"><tr><td valign="top" style="padding-right:18px;">${image}</td><td>${details}</td></tr></table>`:details}</td></tr>`;else content=`<tr>${image?`<td valign="top" style="padding-right:18px;border-right:2px solid ${accent};">${image}</td>`:''}<td style="${image?'padding-left:18px;':'border-left:3px solid '+accent+';padding-left:16px;'}">${details}</td></tr>`;
if(data.disclaimer?.trim()){content+=`<tr><td colspan="2" style="padding-top:16px;max-width:520px;font-family:${font};font-size:11px;line-height:1.6;color:${color};">${esc(data.disclaimer).replace(/\n/g,'<br>')}</td></tr>`;plain.push(data.disclaimer.trim())}
const html=`<table role="presentation" cellpadding="0" cellspacing="0" border="0" style="font-family:${font};background-color:${background};color:${color};font-size:${size}px;line-height:1.5;"><tbody>${content}</tbody></table>`;return {html,text:plain.join('\n')};}
root.ToolHubSignature={build,fonts};
})(globalThis);
